<?php
namespace App\Models; use Illuminate\Database\Eloquent\Model; use Illuminate\Database\Eloquent\SoftDeletes; use Illuminate\Database\Eloquent\Relations\BelongsTo; use Illuminate\Database\Eloquent\Relations\HasMany; use Illuminate\Database\Eloquent\Relations\BelongsToMany;
class Experience extends Model {use SoftDeletes; protected $fillable=['user_id','exam_id','title','slug','summary','body','exam_date','exam_year','shift','stage','language','difficulty','subject_difficulties','attempted_count','estimated_correct','estimated_incorrect','good_attempt','time_management','unexpected_topics','exam_day_notes','preparation_strategy','recommended_resources','mistakes_to_avoid','advice','center_region','anonymous_author','status','verification_label','published_at']; protected function casts():array{return ['exam_date'=>'date','subject_difficulties'=>'array','anonymous_author'=>'boolean','published_at'=>'datetime'];} public function getRouteKeyName():string{return 'slug';} public function user():BelongsTo{return $this->belongsTo(User::class);} public function exam():BelongsTo{return $this->belongsTo(Exam::class);} public function comments():HasMany{return $this->hasMany(Comment::class)->whereNull('parent_id');} public function allComments():HasMany{return $this->hasMany(Comment::class);} public function likes():HasMany{return $this->hasMany(ExperienceLike::class);} public function bookmarks():HasMany{return $this->hasMany(Bookmark::class);} public function tags():BelongsToMany{return $this->belongsToMany(Tag::class);} public function questions():HasMany{return $this->hasMany(RememberedQuestion::class);} public function revisions():HasMany{return $this->hasMany(ExperienceRevision::class);} public function scopePublished($q){return $q->where('status','published')->whereNotNull('published_at');} }
